//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::sint::int8_of_int`; the
//! native twin is `benches/native/Bench/Int8OfInt.lean`.
//! the Int argument is an Int word, in the int32 range

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::sint;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            sint::int8_of_int(int_unbox(int_box((x >> 33) as i64 - (1 << 30))) as u64) as u64,
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
